"""Build observed-only TEM/SEM reference without modifying source pixels."""
from pathlib import Path
import base64,hashlib,json,platform
from PIL import Image,__version__ as pillow_version
ROOT=Path(__file__).resolve().parents[1];A=ROOT/'assets';W=ROOT/'work/visual-v2/alveolus'
EXISTING=json.loads((A/'ch07-v2-alveolar-provenance.json').read_text(encoding='utf-8'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def copy(source,name,expected):
    target=A/name
    source=target if target.exists() else source
    assert sha(source)==expected
    if source!=target: target.write_bytes(source.read_bytes())
    return {'file':name,'source_file':str(source.relative_to(ROOT)),'sha256':sha(target),'dimensions_px':list(Image.open(target).size),'bytes':target.stat().st_size,'modifications':'None; original source JPEG bytes retained.'}
tem=copy(W/'sources/fphys-14-1142221-g001.jpg','ch07-v2-barrier-tem.jpg','0fdb34f80dfd8a8a2dfee01df808753927fd6cc4605c5d92314197f656d3a7fd')
sem=copy(ROOT/'work/visual-v2/research/B0000716-native.jpg','ch07-v2-alveolar-sem.jpg','5e181861c3c1dbe5aa14ab407191ce11b8360f58a849649431a1db050a638d7a')
assert tem['dimensions_px']==[1059,540] and sem['dimensions_px']==[3966,2753]
encoded=base64.b64encode((A/tem['file']).read_bytes()).decode()
plate=f'''<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1200" height="940" viewBox="0 0 1200 940" role="img" aria-labelledby="title desc"><title id="title">Observed rat alveolar barrier: thin and thicker regions</title><desc id="desc">Complete unchanged Figure 1 A/B. Capillary above and alveolar air below. Original source annotations and both0.5micrometre bars retained. External vector key expands labels; no new anatomical leaders.</desc><rect width="1200" height="940" fill="white"/><g font-family="Arial,Helvetica,sans-serif" fill="#152d37"><text x="48" y="50" font-size="29" font-weight="600">A · Thin region</text><text x="620" y="50" font-size="29" font-weight="600">B · Thicker interstitial region</text><text x="48" y="93" font-size="24">Rat lung · transmission electron microscopy · Cap above / Alv below</text></g><image x="48" y="120" width="1104" height="563" preserveAspectRatio="xMidYMid meet" xlink:href="data:image/jpeg;base64,{encoded}"/><g font-family="Arial,Helvetica,sans-serif" fill="#152d37" font-size="23"><text x="48" y="727" font-size="25" font-weight="600">Source-label key</text><text x="48" y="767">Cap: capillary lumen · Alv: alveolar airspace · Endo: endothelial extension</text><text x="48" y="805">AEC1: type I alveolar epithelial extension · *: basal lamina</text><text x="48" y="843">Col: collagen · IC: interstitial-cell processes (panel B)</text><text x="48" y="890" font-size="24" font-weight="600">Panel A spatial order, from air toward blood:</text><text x="48" y="927">Alv → AEC1 → shared basal lamina (*) → Endo → Cap</text></g></svg>'''
(A/'ch07-v2-barrier-reference.svg').write_text(plate,encoding='utf-8')
style='''*{box-sizing:border-box}html{background:#0e181f}body{margin:0;color:#eff2ee;font:17px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:28px}.eyebrow,.tag{font-size:14px;letter-spacing:.1em;text-transform:uppercase;color:#d8bf95}h1{font:500 clamp(2rem,4.5vw,3.2rem)/1.12 Georgia,serif;letter-spacing:-.02em;margin:10px 0 16px}h2{font:500 1.65rem/1.25 Georgia,serif;margin:0 0 12px}p{margin:.6rem 0}.intro{max-width:940px;color:#c4d2d7}.observed-figure{margin:28px 0 36px;border-top:1px solid #58707a;padding-top:24px}.tag{margin-bottom:9px}.plate{background:white}.plate img{display:block;max-width:100%;width:100%;height:auto}.sem .plate{max-width:1000px;margin:auto}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:15px;margin:16px 0}.actions a{font-size:15px}button{font:inherit;font-size:15px;color:#eef5ef;background:#263f4a;border:1px solid #91abb1;border-radius:3px;padding:9px 14px;cursor:pointer}button:hover{background:#365765}a{color:#a7e2d3;text-underline-offset:3px}button:focus-visible,a:focus-visible,.viewport:focus-visible,summary:focus-visible{outline:3px solid #f2cf91;outline-offset:4px}.caption{max-width:1040px;font-size:16px}.credit{font-size:14px;color:#becfd4}.bridge{padding:15px 20px;border-left:3px solid #b8a27f;background:#172b35;margin:22px 0}.key{border:1px solid #546d77;padding:18px 22px;margin:18px 0}.key dl{display:grid;grid-template-columns:95px 1fr;gap:5px 16px;font-size:16px;margin:0}.key dt{font-weight:650;color:#ead1aa}.key dd{margin:0}summary{cursor:pointer;margin-bottom:10px}footer{font-size:14px;color:#b5c8d0;border-top:1px solid #536b76;padding-top:16px;margin-top:26px}dialog{width:94vw;max-width:1700px;height:94vh;max-height:94vh;padding:18px;border:1px solid #9bafb7;background:#11212a;color:#f2f6ef}dialog::backdrop{background:#000c}.dialogbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:10px}.dialogbar h2{font:500 21px Georgia,serif;flex:1;margin:0}.help{font-size:14px;margin:7px 0;color:#c3d2d6}.viewport{height:calc(100% - 100px);overflow:auto;background:white;overscroll-behavior:contain}.viewport img{display:block;max-width:none;height:auto}@media(max-width:650px){main{padding:18px}.actions{gap:12px}.key{padding:15px}.key dl{grid-template-columns:75px 1fr;gap:7px 10px}}@media(max-width:450px){main{padding:16px}h1{font-size:2.1rem}.dialogbar h2{flex-basis:100%}.dialogbar{gap:8px}dialog{padding:12px}.viewport{height:calc(100% - 155px)}}@media print{@page{size:Letter;margin:15mm}html,body{background:white!important;color:#111!important;color-scheme:light!important}main{padding:0;max-width:none}h1{font-size:24pt;margin:3mm 0}h2{font-size:15pt;margin:0 0 3mm}.eyebrow,.tag{font-size:9pt;color:#222}.intro{font-size:10pt;color:#111;margin:3mm 0}.observed-figure{border:0;padding:0;margin:5mm 0 0;break-inside:avoid;page-break-inside:avoid}.tem .plate{width:180mm;max-width:100%;margin:auto}.sem{break-before:page;page-break-before:always}.sem .plate{width:140mm;max-width:100%;margin:auto}.caption{font-size:9.5pt;line-height:1.35;margin-top:3mm}.credit{font-size:9pt;color:#222;line-height:1.3}.actions,.key,dialog,.screen-only{display:none!important}.bridge{background:white;color:#111;border-left:2pt solid #777;font-size:10pt;line-height:1.35;padding:3mm;margin:4mm 0;break-inside:avoid}a{color:#111}footer{color:#222;font-size:9pt;line-height:1.3;margin-top:5mm;padding-top:3mm;break-inside:avoid}}'''
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Observed alveolar structure — TEM and SEM</title><style>{style}</style><link rel="stylesheet" href="observed-image-dialog.css"><script defer src="observed-image-dialog.js"></script></head><body><main><header><div class="eyebrow">Respiratory physiology · Observed microscopy</div><h1>Observed alveolar structure</h1><p class="intro">Examine the tissue separating alveolar air from blood, then compare a separate surface view. Transmission electron microscopy (TEM) resolves the sectioned barrier; scanning electron microscopy (SEM) reveals surface relief.</p></header>
<figure class="observed-figure tem" id="figure-tem"><div class="tag">Figure 1 · Rat lung · TEM</div><h2>Thin and thicker regions of the alveolar barrier</h2><div class="plate"><img src="ch07-v2-barrier-reference.svg" width="1200" height="940" alt="Complete source Figure1A/B of rat lung. Thin region A and thicker region B retain original Endo, AEC1, asterisks, Cap, Alv, Col, IC and both0.5micrometre bars. External vector key expands source abbreviations."></div><div class="actions"><button type="button" data-enlarge="tem">Enlarge native TEM</button><a href="ch07-v2-barrier-tem.jpg" target="_blank" rel="noopener">Open full publisher Figure 1A/B</a><a href="ch07-v2-barrier-reference.svg" target="_blank" rel="noopener">Full-size reference and key</a></div><figcaption class="caption"><p><strong>A:</strong> type I epithelial extension (AEC1), shared basal lamina (*) and endothelial extension (Endo) separate air from capillary lumen. <strong>B:</strong> separated basal laminae enclose thicker interstitium with collagen (Col) and interstitial-cell processes (IC). The key’s sequence is spatial order, not movement or measured flux.</p><p>These are vascular-perfusion-fixed rat lung sections. The source reports blood-cell-free capillaries in this prepared specimen; this does not imply living capillaries lack red cells. The source’s 0.5 μm bars apply to their own panels.</p><p class="credit">Knudsen, Hummel, Wrede, Zimmermann, Perlman &amp; Smith (2023), Figure 1A/B, <em>Acinar micromechanics in health and lung injury</em>. <a href="https://doi.org/10.3389/fphys.2023.1142221">Owning article</a> · <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>. Complete publisher JPEG unchanged; original annotations/bars retained. External vector key added; no anatomical leaders.</p></figcaption><details class="key"><summary>Accessible source-label key and preparation</summary><dl><dt>Cap</dt><dd>Capillary lumen.</dd><dt>Alv</dt><dd>Alveolar airspace.</dd><dt>Endo</dt><dd>Endothelial extension.</dd><dt>AEC1</dt><dd>Type I alveolar epithelial extension.</dd><dt>*</dt><dd>Basal lamina; shared in thin region A, separated around thicker interstitium in B.</dd><dt>Col / IC</dt><dd>Collagen / interstitial-cell processes in panel B.</dd></dl><p>Panel A, from air toward blood: <strong>Alv → AEC1 → shared basal lamina (*) → Endo → Cap.</strong></p><p>Perfusion fixation through the vena cava caudalis at 5 cmH₂O airway opening pressure during expiration, after two recruitment maneuvers with a 3-second pause at 30 cmH₂O. Age, sex, strain and disease status are not supplied in the figure caption.</p></details></figure>
<figure class="observed-figure sem" id="figure-sem"><div class="tag">Figure 2 · Separate alveolar surface · SEM</div><h2>Observed surface relief</h2><p class="bridge">Different specimens, preparations and scales: complementary observations, not a registered zoom.</p><div class="plate"><img src="ch07-v2-alveolar-sem.jpg" width="3966" height="2753" alt="Unmodified monochrome scanning electron micrograph of alveoli, showing prepared surface relief. No particular cell, pore, capillary or calibrated scale is assigned."></div><div class="actions"><button type="button" data-enlarge="sem">Enlarge native SEM</button><a href="ch07-v2-alveolar-sem.jpg" target="_blank" rel="noopener">Open full Wellcome SEM</a></div><figcaption class="caption"><p>Scanning electron micrograph of alveoli. The catalogue does not supply species, physical field width, preparation or normal/pathological status. This is a whole surface field; no individual protrusion, opening, capillary or cell is identified. Grayscale microscopy contrast does not show natural living-tissue color.</p><p class="credit"><em>Alveoli. SEM</em>, David Gregory &amp; Debbie Marshall. Wellcome Collection, B0000716. <a href="https://wellcomecollection.org/works/md3e2shq">Owning record</a> · <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>. Native 3966 × 2753 JPEG retained unchanged; no crop, recoloring, added scale or anatomical overlay.</p></figcaption></figure>
<footer><p class="screen-only">Native enlargement: Tab to an enlargement button and press Enter/Space. Focus the image region and pan with arrow keys or scroll. Native size restores source-pixel dimensions; Fit view shows the whole image. Escape or Close image returns to the page.</p><p><a href="ch07-v2-alveolar-provenance.json">Exact sources, preparation, native pixels, print resolution and hashes</a>.</p></footer></main>
<dialog id="enlargement" aria-labelledby="enlargement-title"><div class="dialogbar"><h2 id="enlargement-title">Native image</h2><button type="button" id="native">Native size</button><button type="button" id="fit">Fit view</button><button type="button" id="close">Close image</button></div><p class="help">Display size only. Focus the image region and use arrow keys to pan; Escape closes.</p><div class="viewport" tabindex="0" role="region" aria-label="Scrollable full-size microscopy"><img id="enlarged-image" alt=""></div></dialog>'''
js='''<script>(()=>{'use strict';const dialog=document.getElementById('enlargement'),image=document.getElementById('enlarged-image'),viewport=dialog.querySelector('.viewport');const media={tem:{src:'ch07-v2-barrier-tem.jpg',width:1059,title:'Rat lung TEM — complete publisher Figure 1A/B',alt:'Unchanged TEM with both panels, source labels and both0.5micrometre bars. Cap above, Alv below.'},sem:{src:'ch07-v2-alveolar-sem.jpg',width:3966,title:'Alveoli — native Wellcome SEM',alt:'Unmodified Wellcome alveolar SEM. Species and scale unspecified.'}};let selected=null,opener=null;function native(){image.style.width=selected.width+'px';image.style.maxWidth='none';}document.querySelectorAll('[data-enlarge]').forEach(button=>button.addEventListener('click',()=>{opener=button;selected=media[button.dataset.enlarge];image.src=selected.src;image.alt=selected.alt;document.getElementById('enlargement-title').textContent=selected.title;native();dialog.showModal();viewport.scrollTop=0;viewport.scrollLeft=0;viewport.focus();}));document.getElementById('native').addEventListener('click',native);document.getElementById('fit').addEventListener('click',()=>{image.style.width='100%';image.style.maxWidth=selected.width+'px';});document.getElementById('close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{if(opener)opener.focus();});})();</script></body></html>'''
